import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_range(start, end):
    if start > end:
        return 1
    return reduce(lcm, range(start, end + 1))

N_values = range(1, 6)
K_values = range(1, 11)
results = {}

for n in N_values:
    x_k_sequence = {}
    for k in K_values:
        # x_k = lcm(k, k+1, ..., k+n-1)
        end = k + n - 1
        x_k = lcm_range(k, end)
        x_k_sequence[k] = x_k
    results[n] = x_k_sequence

# Print results in a readable format
for n, seq in results.items():
    print(f"--- n = {n} ---")
    # Print pairs (k, x_k)
    print(f"k=1: {seq[1]}")
    for k in range(2, 11):
        print(f"k={k}: {seq[k]}")

    # Check local trend: x_{k+1} vs x_k for k=1 to 9
    print("\nDifferences (x_{k+1} vs x_k):")
    for k in range(1, 10):
        x_k = seq[k]
        x_k_plus_1 = seq[k+1]
        comparison = "INCREASING (>)" if x_k_plus_1 > x_k else "NON-INCREASING (<=)"
        print(f"k={k} to k={k+1}: {comparison}")
